export class Sekai64Error extends Error {
    code;
    path;
    backend;
    details;
    constructor(message, context) {
        super(message);
        this.name = 'Sekai64Error';
        this.code = context.code;
        this.path = context.path;
        this.backend = context.backend;
        this.details = context.details;
    }
}